INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:gemini-cli:cli-surface-v1','project_tool','seed://gemini-cli/cli-surface','Gemini CLI command surface','Snapshot date: 2026-07-15. Commands and tools: /help, /about, /auth, /bug, /chat, /clear, /compress, /directory, /docs, /editor, /extensions, /hooks, /ide, /init, /mcp, /memory, /model, /privacy, /quit, /restore, /settings, /stats, /theme, /tools; gemini --help, --include-directories, --yolo. Configuration model: ~/.gemini/settings.json, .gemini/settings.json, GEMINI.md; MCP servers and hooks in settings. Source: https://google-gemini.github.io/gemini-cli/docs/cli/commands.html (verified 2026-07-15).','https://google-gemini.github.io/gemini-cli/docs/cli/commands.html (verified 2026-07-15)','2a0fa67995834287393be2be58add407a87373339bacd1a1672fd94298e41ac9','gemini-cli,cli,command-surface,provenance',2.2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:gemini-cli:config-model-v1','project_doc','seed://gemini-cli/config-model','Gemini CLI command surface configuration model','Snapshot date: 2026-07-15. Canonical configuration paths: ~/.gemini/settings.json, .gemini/settings.json, GEMINI.md; MCP servers and hooks in settings. Registration is additive, idempotent, and must preserve user-owned keys, hooks, rules, and MCP servers. Source: https://google-gemini.github.io/gemini-cli/docs/cli/commands.html (verified 2026-07-15).','https://google-gemini.github.io/gemini-cli/docs/cli/commands.html (verified 2026-07-15)','da9ae20d3006dd8f0db831e416c00b70b3a324157d3438c722ea44d91a7a7d7b','gemini-cli,config,mcp,rules',2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:gemini-cli:integration-points-v1','project_doc','seed://gemini-cli/integration','Gemini CLI command surface Simplicio integration points','Snapshot date: 2026-07-15. T2 MCP plus rules; use dated official snapshot and no network at runtime. Simplicio execution remains the governed control plane; provider surfaces are compatibility inputs, not alternate mutation paths. Source: https://google-gemini.github.io/gemini-cli/docs/cli/commands.html (verified 2026-07-15).','https://google-gemini.github.io/gemini-cli/docs/cli/commands.html (verified 2026-07-15)','e8daa8c6b0958f8f08896d818021f7186fee7930718d4db19fcdeac6259638d0','gemini-cli,simplicio,integration,governance',2);
